// DeleteUniqueIndexCache 删除索引存在的缓存
func (h *HomeworkAssistantRecordRepo) DeleteIndexCache(ctx context.Context, data ...*devices_learn_model.HomeworkAssistantRecord) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, h.cache.Key(CacheHomeworkAssistantRecordByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[h.cache.Key(CacheHomeworkAssistantRecordByIDPrefix, item.ID)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantRecordBySNIDUserIDPrefix, item.SNID, item.UserID)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantRecordByQuestionIDPrefix, item.QuestionID)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantRecordByUserIDQuestionTextMd5SumPrefix, item.UserID, item.QuestionTextMd5Sum)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantRecordBySNIDPrefix, item.SNID)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantRecordByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := h.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
